gold_sql:
SELECT month, COUNT(*) applications, SUM(fraud_bool) frauds,
 ROUND(100.0*AVG(fraud_bool),3) fraud_rate_pct
 FROM applications GROUP BY month ORDER BY month;

WITH b AS (SELECT fraud_bool, NTILE(5) OVER (ORDER BY name_email_similarity) quintile FROM applications)
 SELECT quintile, COUNT(*) applications, SUM(fraud_bool) frauds,
 ROUND(100.0*AVG(fraud_bool),3) fraud_rate_pct FROM b GROUP BY 1 ORDER BY 1;

WITH b AS (SELECT fraud_bool, NTILE(5) OVER (ORDER BY session_length_in_minutes) quintile FROM applications)
 SELECT quintile, COUNT(*) applications, SUM(fraud_bool) frauds,
 ROUND(100.0*AVG(fraud_bool),3) fraud_rate_pct FROM b GROUP BY 1 ORDER BY 1;

WITH b AS (SELECT fraud_bool, NTILE(10) OVER (ORDER BY velocity_6h) decile FROM applications)
 SELECT decile, COUNT(*) applications, SUM(fraud_bool) frauds,
 ROUND(100.0*AVG(fraud_bool),3) fraud_rate_pct FROM b GROUP BY 1 ORDER BY 1;

SELECT device_distinct_emails_8w email_count_8w, COUNT(*) applications,
 SUM(fraud_bool) frauds, ROUND(100.0*AVG(fraud_bool),3) fraud_rate_pct
 FROM applications GROUP BY 1 ORDER BY 1;

WITH b AS (SELECT fraud_bool, NTILE(10) OVER (ORDER BY credit_risk_score DESC, hash(name_email_similarity, days_since_request, velocity_6h)) decile FROM applications)
 SELECT decile, COUNT(*) applications, SUM(fraud_bool) frauds,
 ROUND(100.0*AVG(fraud_bool),3) fraud_rate_pct FROM b GROUP BY 1 ORDER BY 1;

SELECT month, source, COUNT(*) applications, SUM(fraud_bool) frauds,
 ROUND(100.0*AVG(fraud_bool),3) fraud_rate_pct
 FROM applications GROUP BY 1,2 ORDER BY 1,2;
